import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Radio from "../../ui/radio";

// MODEL

export const AppleValue = S.Union([
  S.Literal("fuji-apple"),
  S.Literal("gala-apple"),
  S.Literal("granny-smith-apple"),
]);
export type AppleValue = typeof AppleValue.Type;

export const Model = S.Struct({
  selectedApple: AppleValue,
});

export type Model = typeof Model.Type;

// MESSAGE

export const SelectedApple = m("SelectedApple", { value: AppleValue });
export const Message = S.Union([SelectedApple]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ selectedApple: "fuji-apple" }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      SelectedApple: ({ value }) => [
        evo(model, { selectedApple: () => value }),
        [],
      ],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>(
  (model): Html =>
    Radio.groupView<Message>({
      label: "Best apple",
      labelId: "best-apple-label",
      children: [
        Radio.itemView<Message>({
          value: "fuji-apple",
          selectedValue: model.selectedApple,
          label: "Fuji",
          onValueChange: SelectedApple({ value: "fuji-apple" }),
        }),
        Radio.itemView<Message>({
          value: "gala-apple",
          selectedValue: model.selectedApple,
          label: "Gala",
          onValueChange: SelectedApple({ value: "gala-apple" }),
        }),
        Radio.itemView<Message>({
          value: "granny-smith-apple",
          selectedValue: model.selectedApple,
          label: "Granny Smith",
          onValueChange: SelectedApple({ value: "granny-smith-apple" }),
        }),
      ],
    })
);

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeProgram({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Radio Basic",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as RadioBasicExample from "./main";

describe("Radio Basic example", () => {
  test("matches the Base UI radio hero selection behavior", () => {
    Scene.scene(
      {
        update: RadioBasicExample.update,
        view: RadioBasicExample.view,
      },
      Scene.with(RadioBasicExample.init()[0]),
      Scene.expect(Scene.role("radiogroup", { name: "Best apple" })).toExist(),
      Scene.expect(Scene.role("radio", { name: "Fuji" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.click(Scene.text("Granny Smith")),
      Scene.expect(Scene.role("radio", { name: "Fuji" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.expect(Scene.role("radio", { name: "Granny Smith" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });
});
